entries[452402] = { ["name"] = "Demonsurge", ["text"] = "Havoc\nMetamorphosis now also causes Demon's Bite to generate 15 additional Fury.\n\nWhile demon form is active, the first cast of each empowered ability induces a Demonsurge, causing you to explode with Fel energy, dealing (330% of Attack Power) Fire damage to nearby enemies. Deals reduced damage beyond 8 targets.\n\nVengeance\nMetamorphosis now also greatly empowers Soul Cleave and Spirit Bomb.\n\nWhile demon form is active, the first cast of each empowered ability induces a Demonsurge, causing you to explode with Fel energy, dealing (330% of Attack Power) Fire damage to nearby enemies. Deals reduced damage beyond 8 targets." }
entries[452403] = { ["name"] = "Wave of Debilitation", ["text"] = "Chaos Nova slows enemies by 60% and reduces attack and cast speed by 15% for 5 sec after its stun fades." }
