entries[452405] = { ["name"] = "Focused Hatred", ["text"] = "Demonsurge deals 50% increased damage when it strikes a single target.\n\nEach additional target reduces this bonus by 10%." }
entries[452406] = { ["name"] = "Set Fire to the Pain", ["text"] = "5% of all non-Fire damage taken is instead taken as Fire damage over 6 sec.\n\nFire damage taken reduced by 10%." }
entries[452407] = { ["name"] = "Improved Soul Rending", ["text"] = "Leech granted by Soul Rending increased by 2% and an additional 2% while Metamorphosis is active." }
entries[452408] = { ["name"] = "Burning Blades", ["text"] = "Havoc\nYour blades burn with Fel energy, causing your Chaos Strike, Throw Glaive, and auto-attacks to deal an additional 50% damage as Fire over 6 sec.\n\nVengeance\nYour blades burn with Fel energy, causing your Soul Cleave, Throw Glaive, and auto-attacks to deal an additional 40% damage as Fire over 6 sec." }
entries[452409] = { ["name"] = "Violent Transformation", ["text"] = "Vengeance\nWhen you activate Metamorphosis, the cooldowns of your Sigil of Flame and Fel Devastation are immediately reset.\n\nHavoc\nWhen you activate Metamorphosis, the cooldowns of your Sigil of Flame and Immolation Aura are immediately reset." }
entries[452410] = { ["name"] = "Enduring Torment", ["text"] = "Havoc\nThe effects of your demon form persist outside of it in a weakened state, increasing Chaos Strike and Blade Dance damage by 15%, and Haste by 5%.\n\nVengeance\nThe effects of your demon form persist outside of it in a weakened state, increasing maximum health by 5% and Armor by 20%." }
